/**
 * @fileOverview    Sends authentication emails through Resend.
 * @module          authentication
 */

import {DEFAULT_FROM} from "@/features/auth/constants/policy";
import {RESEND_EMAILS, RESEND_ERRORS,} from "@/features/auth/constants/resend";
import {Resend} from "resend";

/**
 * Sends an email-verification link.
 *
 * @param to       Recipient address.
 * @param url      Verification URL generated by Better Auth.
 *
 * @throws         Error if the Resend API key is missing or email delivery fails.
 */
export async function sendVerificationEmail(
    to: string,
    url: string,
): Promise<void> {

    const apiKey = process.env.RESEND_API_KEY;

    if (!apiKey) {
        throw new Error(RESEND_ERRORS.RESEND_KEY_NOT_CONFIG);
    }

    const resend = new Resend(apiKey);
    const template = RESEND_EMAILS.EMAIL_VERIFICATION;

    const {error} = await resend.emails.send({
        from: process.env.RESEND_FROM_EMAIL ?? DEFAULT_FROM,
        to,
        subject: template.subject,
        text: template.text(url),
    });

    if (error) {
        throw new Error(RESEND_ERRORS.RESEND_EMAIL_FAILURE + `${error.message}`);
    }
}
